//! Rust bindings for NVIDIA's isaac_ros_visual_slam_interfaces (VisualSlamStatus, Reset, ...).
//!
//! The Isaac ROS debs ship no Rust bindings. msg.rs, srv.rs and */rmw.rs were generated by
//! rosidl_generator_rs from the installed .msg/.srv files (regenerate.sh) and are unchanged. They
//! link NVIDIA's installed C libraries (libisaac_ros_visual_slam_interfaces__rosidl_*.so), so the
//! type support, type names and type hashes are NVIDIA's own. Only this file is hand-written: like
//! ros-env does for the packages in /opt/ros, it puts the message packages the generated code
//! refers to (std_msgs, geometry_msgs) in scope.
#![allow(non_camel_case_types, missing_docs, unused_imports, unexpected_cfgs, clippy::all)]

pub mod msg {
    use ros_env::{geometry_msgs, std_msgs};
    include!("msg.rs");
    pub mod rmw {
        use ros_env::{geometry_msgs, std_msgs};
        include!("msg/rmw.rs");
    }
}

pub mod srv {
    use ros_env::{geometry_msgs, std_msgs};
    include!("srv.rs");
    pub mod rmw {
        use ros_env::{geometry_msgs, std_msgs};
        include!("srv/rmw.rs");
    }
}